// Demo workflow: turns a submitted checklist into one record.
// Zero credentials and no outbound calls. It exists so a fresh install has a
// second form button in the dashboard's Actions section, with real fields
// rather than an empty submit.
return items.map((item) => {
  const form = item.json || {};
  return {
    json: {
      operator: form.Operator || 'unknown',
      shift: form.Shift || 'unspecified',
      notes: form.Notes || '',
      recorded_at: new Date().toISOString(),
    },
  };
});
